// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address to, uint256 v) public {
        vm.assume(to != address(0));
        vm.assume(caddress != address(0));
        address[] memory _tos = new address[](1);
        _tos[0] = to;
        uint256[] memory vals = new uint256[](1);
        vals[0] = v;
        // We expect the call to succeed (not revert) when _tos has exactly one element
        (bool success,) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, vals));
        assertTrue(success);
    }
}

